big_roll_code = #{bigRollCode}, remind_flag = #{remindFlag}, del_flag = #{delFlag}, create_by = #{createBy}, create_time = #{createTime}, update_by = #{updateBy}, update_time = #{updateTime}, remark = #{remark},
